create or replace function public.iara_execution_idempotency_guard() returns trigger language plpgsql set search_path=public as $$ begin if TG_OP='UPDATE' then if NEW.tenant_id <> OLD.tenant_id or NEW.idempotency_key <> OLD.idempotency_key or NEW.tool_key <> OLD.tool_key or NEW.tool_version <> OLD.tool_version or NEW.request_hash <> OLD.request_hash or NEW.execution_id <> OLD.execution_id or NEW.created_at <> OLD.created_at then raise exception 'IARA idempotency identity fields are immutable'; end if; end if; return NEW; end $$; revoke all on function public.iara_execution_idempotency_guard() from public, anon, authenticated; grant execute on function public.iara_execution_idempotency_guard() to service_role;